@layer theme, base, components, utilities;

@layer components {
  .icon {
    flex-shrink: 0;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    overflow: visible;
    fill: none;
    stroke: currentColor;
    stroke-width: var(--ui-icon-stroke, 1.5);
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* A chevron is one size everywhere (--ui-icon-chevron), a step under the
     icons around it. */
  .icon[data-icon^="chevron"] {
    width: var(--ui-icon-chevron);
    height: var(--ui-icon-chevron);
  }

  /* A disclosure chevron that points right and opens downward turns a
     quarter turn (data-turn="open"): changing axis, a morph between the two
     shapes reads as the arrow coming apart, so this one rotates, on the glide
     curve with no overshoot. Down/up chevrons morph instead. */
  .icon.icon[data-turn] {
    /* Doubled class: outranks a component's own `transition` on its chevron
       (usually its hover color), so both are listed here. */
    transition:
      rotate var(--ui-dur-base) var(--ui-ease-glide),
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .icon[data-turn="open"] {
    rotate: 90deg;
  }

  :is([dir="rtl"]) .icon[data-turn] {
    scale: -1 1;
  }

  :is([dir="rtl"]) .icon[data-turn="open"] {
    rotate: -90deg;
  }

  @media (prefers-reduced-motion: reduce) {
    .icon.icon[data-turn] {
      transition: color var(--ui-dur-instant) var(--ui-ease-color);
    }
  }

  /* The gap (3) must exceed any path plus margins so the dash never repeats. */
  .stroke {
    stroke-dasharray: var(--len, 1) 3;
    stroke-dashoffset: var(--on, 0);
    transform-box: fill-box;
    transform-origin: center;
    /* --icon-morph-ease: set to --ui-ease-glide where a morph should land
       without overshoot (a result, not a toggle). */
    transition:
      d var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      stroke-dasharray var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      stroke-dashoffset var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      rotate var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* A stroke that leaves (copy's sheets as the check arrives) gets out of
     the way: it erases, fades and draws in slightly, all quickly, so the two
     shapes never tangle in the same spot. */
  .stroke[data-off] {
    stroke-dashoffset: var(--off, 1.3);
    opacity: 0;
    scale: 0.85;
    transition:
      stroke-dashoffset var(--ui-dur-fast) var(--ui-ease-exit),
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      scale var(--ui-dur-fast) var(--ui-ease-exit),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* A stroke that arrives waits a beat for the old one to clear, then draws
     on in one clean pass. */
  .stroke[data-enter] {
    transition:
      stroke-dashoffset var(--ui-dur-base) var(--ui-ease-draw) calc(var(--ui-dur-instant) * 0.6),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* Two strokes that meet end to end at rest (copy's sheet and rim): the
     moving one lands without overshoot, so the seam never opens, and the
     other erases in place along its path instead of fading and shrinking, so
     copy → check reads as one line opening at its corner. */
  .stroke.seam:not([data-enter]) {
    transition:
      d var(--ui-dur-glide) var(--ui-ease-glide),
      stroke-dasharray var(--ui-dur-glide) var(--ui-ease-glide),
      stroke-dashoffset var(--ui-dur-glide) var(--ui-ease-glide),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .stroke.seam[data-off] {
    opacity: 1;
    scale: none;
    transition:
      stroke-dashoffset var(--ui-dur-instant) var(--ui-ease-draw),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  @starting-style {
    .icon[data-ready] .stroke[data-enter] {
      stroke-dashoffset: var(--off, 1.3);
    }
  }

  .block {
    stroke-width: 4;
  }

  /* Mask copy of a cut stroke: gaps the other strokes on both sides of it. */
  .cut {
    stroke: black;
    stroke-width: calc(var(--ui-icon-stroke, 1.5) * 3);
  }

  /* ---------- Parent hover ---------- */

  @media (hover: hover) {
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .lid {
      translate: 0 -1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .out {
      translate: 1px -1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .drop {
      translate: 0 1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .forward {
      translate: 1px 0;
    }
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .lid {
    translate: 0 -1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .out {
    translate: 1px -1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .drop {
    translate: 0 1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .forward {
    translate: 1px 0;
  }

  @media (prefers-reduced-motion: reduce) {
    .stroke,
    .stroke[data-off],
    .stroke[data-enter],
    .stroke.seam:not([data-enter]),
    .stroke.seam[data-off] {
      transition: none;
    }
  }
}

"use client";

import { useId, useState, type ComponentProps, type CSSProperties } from "react";
import styles from "./icons.module.css";

/*
 * Each icon is a few keyed strokes on a 16px grid. When `name` changes, a key
 * in both icons morphs (`d` only interpolates when the commands match); old-only
 * keys retract, new-only keys draw in. Give pairs shared keys so little ink moves.
 * Strokes use pathLength 1; a window f/t must touch a path end so it can retract.
 */

type Stroke = {
  d: string;
  /** Visible window along the path, 0–1. One end must touch the path's end. */
  f?: number;
  t?: number;
  /** Cut a gap in the other strokes along this line. */
  cut?: boolean;
  /** Draw as a solid rounded block. */
  block?: boolean;
  /** Degrees, about its own midpoint. */
  rot?: number;
  /** Meets another stroke end to end at rest: morphs without overshoot and
   *  erases in place (no fade or shrink) so the seam never shows. */
  seam?: boolean;
  /** Nudges 1px while the parent control is hovered or focused. */
  fx?: "lid" | "drop" | "out" | "forward";
};

/* Copy's front sheet is two strokes that meet end to end. `sheet` is its left
   edge, bottom-left corner and bottom edge: turned 45° that corner is a check,
   so copy → check moves those points while `rim` (the rest of the square)
   erases from the bottom-right corner round to the top-left. */
const SHEET = {
  d: "M5.76 5.76 C5.43 6.09 5.25 6.54 5.25 7 L5.25 11.5 C5.25 12.47 6.03 13.25 7 13.25 L11.5 13.25",
  seam: true,
} satisfies Stroke;
const RIM = {
  d: "M5.76 5.76A1.75 1.75 0 0 1 7 5.25H11.5A1.75 1.75 0 0 1 13.25 7V11.5A1.75 1.75 0 0 1 11.5 13.25",
  seam: true,
} satisfies Stroke;
// The same commands as SHEET; the corner is a short curve so it can come from the rounded one.
const CHECK = {
  d: "M3.75 8.25 C3.96 8.46 4.17 8.67 4.38 8.88 L6.4 10.9 C6.75 11.25 6.75 11.25 7.08 10.87 L12.25 5",
  seam: true,
} satisfies Stroke;
const BACK_SHEET = "M9.25 2.75H4.5A1.75 1.75 0 0 0 2.75 4.5V9.25";
const EYE = "M1.75 8C3.1 5.1 5.4 3.5 8 3.5s4.9 1.6 6.25 4.5C12.9 10.9 10.6 12.5 8 12.5S3.1 10.9 1.75 8Z";
const PUPIL = "M6 8a2 2 0 1 0 4 0a2 2 0 1 0-4 0";
const RING = "M14.25 8a6.25 6.25 0 1 1-12.5 0a6.25 6.25 0 1 1 12.5 0";
const CHANGE_FRAME = "M2.75 5.75a3 3 0 0 1 3-3h4.5a3 3 0 0 1 3 3v4.5a3 3 0 0 1-3 3h-4.5a3 3 0 0 1-3-3Z";

const CHEVRON_V = ["M2.87 8 L8.88 8", "M7.12 8 L13.13 8"] as const;
const CHEVRON_H = ["M5 5.875 L11 5.875", "M5 10.125 L11 10.125"] as const;

const ARROW_UP = {
  s: { d: "M8 3.25 L8 12.75" },
  h1: { d: "M8 3.25 L3.75 7.5" },
  h2: { d: "M8 3.25 L12.25 7.5" },
};

const ICONS = {
  eye: { eye: { d: EYE }, pupil: { d: PUPIL } },
  "eye-off": { eye: { d: EYE }, pupil: { d: PUPIL }, slash: { d: "M2.75 2.75 L13.25 13.25", cut: true } },
  copy: { back: { d: BACK_SHEET }, sheet: SHEET, rim: RIM },
  check: { sheet: CHECK },
  duplicate: { back: { d: BACK_SHEET }, sheet: SHEET, rim: RIM, add: { d: "M9.25 7.5v3.5M7.5 9.25h3.5" } },
  plus: { a: { d: "M3.25 8 L12.75 8" }, b: { d: "M8 12.75 L8 3.25" } },
  close: { a: { d: "M4.75 4.75 L11.25 11.25" }, b: { d: "M4.75 11.25 L11.25 4.75" } },
  minus: { a: { d: "M3.25 8 L12.75 8" } },
  menu: {
    a: { d: "M2.75 4.75 L13.25 4.75" },
    m: { d: "M2.75 8 L13.25 8" },
    b: { d: "M2.75 11.25 L13.25 11.25" },
  },
  "arrow-up": ARROW_UP,
  send: ARROW_UP,
  "arrow-down": {
    s: { d: "M8 3.25 L8 12.75" },
    h1: { d: "M8 12.75 L3.75 8.5" },
    h2: { d: "M8 12.75 L12.25 8.5" },
  },
  "arrow-left": {
    s: { d: "M3.25 8 L12.75 8" },
    h1: { d: "M3.25 8 L7.5 3.75" },
    h2: { d: "M3.25 8 L7.5 12.25" },
  },
  "arrow-right": {
    s: { d: "M3.25 8 L12.75 8", fx: "forward" },
    h1: { d: "M12.75 8 L8.5 3.75", fx: "forward" },
    h2: { d: "M12.75 8 L8.5 12.25", fx: "forward" },
  },
  "chevron-up": { a: { d: CHEVRON_V[0], rot: -45 }, b: { d: CHEVRON_V[1], rot: 45 } },
  "chevron-down": { a: { d: CHEVRON_V[0], rot: 45 }, b: { d: CHEVRON_V[1], rot: -45 } },
  "chevron-left": { a: { d: CHEVRON_H[0], rot: -45 }, b: { d: CHEVRON_H[1], rot: 45 } },
  "chevron-right": { a: { d: CHEVRON_H[0], rot: 45 }, b: { d: CHEVRON_H[1], rot: -45 } },
  stop: { block: { d: "M6 6 L10 6 L10 10 L6 10 Z", block: true } },
  mic: {
    capsule: { d: "M8 2.25a2.25 2.25 0 0 0-2.25 2.25v3.25a2.25 2.25 0 0 0 4.5 0V4.5A2.25 2.25 0 0 0 8 2.25Z" },
    cradle: { d: "M3.75 7.5a4.25 4.25 0 0 0 8.5 0" },
    stand: { d: "M8 11.75v2" },
  },
  // Pause's right bar is drawn with play's commands (a line through its own
  // midpoint), so it bends out into the triangle's point while the left bar
  // stays put: one motion, nothing erased or drawn in. On the glide (seam),
  // so the bar never bows past straight on its way back.
  play: {
    l: { d: "M5.25 12.5 L5.25 3.5", seam: true },
    t: { d: "M5.25 3.5 L12.25 8 L5.25 12.5", seam: true },
  },
  pause: {
    l: { d: "M5.75 12.25 L5.75 3.75", seam: true },
    t: { d: "M10.25 3.75 L10.25 8 L10.25 12.25", seam: true },
  },
  search: {
    ring: { d: "M11.75 7.25a4.5 4.5 0 1 1-9 0a4.5 4.5 0 1 1 9 0" },
    handle: { d: "M10.5 10.5 L13.25 13.25" },
  },
  link: {
    l1: { d: "M6.75 9.25 9.25 6.75" },
    l2: { d: "M7.4 4.6 8.2 3.8a2.65 2.65 0 0 1 3.75 3.75l-.8.8" },
    l3: { d: "M8.6 11.4 7.8 12.2a2.65 2.65 0 0 1-3.75-3.75l.8-.8" },
  },
  download: {
    arrow: { d: "M8 2.75v7M4.75 6.75 8 10l3.25-3.25", fx: "drop" },
    base: { d: "M3 13.25h10" },
  },
  trash: {
    lid: { d: "M2.75 4.5h10.5M6.25 4.5V3.5a1 1 0 0 1 1-1h1.5a1 1 0 0 1 1 1v1", fx: "lid" },
    can: { d: "M4.25 4.5l.6 8a1.35 1.35 0 0 0 1.35 1.25h3.6a1.35 1.35 0 0 0 1.35-1.25l.6-8" },
  },
  external: { out: { d: "M4.75 11.25 11.25 4.75M5.75 4.75h5.5v5.5", fx: "out" } },
  upload: {
    arrow: { d: "M8 10.25v-7.5M4.75 6 8 2.75 11.25 6", fx: "lid" },
    base: { d: "M3 13.25h10" },
  },
  file: {
    sheet: { d: "M4.25 3.75A1.5 1.5 0 0 1 5.75 2.25h3.5l3.5 3.5v6.5a1.5 1.5 0 0 1-1.5 1.5h-5.5a1.5 1.5 0 0 1-1.5-1.5Z" },
    fold: { d: "M9.25 2.5v3.25h3.25" },
  },
  /* The arc runs into a short straight lead, and the head is a clean
     corner at its end, so the two never pile up into a blob. */
  retry: {
    arc: { d: "M13.5 8a5.5 5.5 0 1 1-5.5-5.5c1.54 0 3.01.61 4.12 1.67L13.5 5.5" },
    head: { d: "M13.5 2.44 L13.5 5.5 L10.44 5.5" },
  },
  calendar: {
    body: { d: "M2.75 5.25A1.75 1.75 0 0 1 4.5 3.5h7a1.75 1.75 0 0 1 1.75 1.75v6.5a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    bar: { d: "M2.75 7.25 L13.25 7.25" },
    pins: { d: "M5.5 2.25v2.5M10.5 2.25v2.5" },
  },
  /* Dots are near-zero-length strokes drawn by the round cap. */
  info: {
    ring: { d: RING },
    stem: { d: "M8 7.25 L8 11.25" },
    dot: { d: "M8 4.75 L8 4.76" },
  },
  alert: {
    ring: { d: RING },
    stem: { d: "M8 4.75 L8 8.5" },
    dot: { d: "M8 11.25 L8 11.26" },
  },
  "check-circle": {
    ring: { d: RING },
    tick: { d: "M5.5 8.25 L7.25 10 L10.5 6.25" },
  },
  /* Three dots in a row: the overflow menu on a row or a card. */
  more: {
    a: { d: "M3.75 8 L3.76 8" },
    dot: { d: "M8 8 L8.01 8" },
    b: { d: "M12.25 8 L12.26 8" },
  },
  pencil: {
    body: { d: "M10.25 3.25a1.5 1.5 0 0 1 2.12 0l.38.38a1.5 1.5 0 0 1 0 2.12L6.5 12 3 13l1-3.5Z" },
    edge: { d: "M9.25 4.25 L11.75 6.75" },
  },
  /* A panel with its side column: show or hide a sidebar. */
  sidebar: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M6.25 2.75 L6.25 13.25" },
  },
  warning: {
    tri: { d: "M6.92 3.1a1.25 1.25 0 0 1 2.16 0l5 8.65a1.25 1.25 0 0 1-1.08 1.875H3a1.25 1.25 0 0 1-1.08-1.875Z" },
    stem: { d: "M8 6.25 L8 9" },
    dot: { d: "M8 11.25 L8 11.26" },
  },
  /* App chrome: places, tools and panes an app's frame needs. Static. */
  home: {
    roof: { d: "M2.25 7.25 8 2.5l5.75 4.75" },
    body: { d: "M3.75 6v6.25a1 1 0 0 0 1 1h6.5a1 1 0 0 0 1-1V6" },
    door: { d: "M6.75 13.25v-3h2.5v3" },
  },
  compose: {
    frame: { d: "M13.25 8.75v3a1.5 1.5 0 0 1-1.5 1.5h-7.5a1.5 1.5 0 0 1-1.5-1.5v-7.5a1.5 1.5 0 0 1 1.5-1.5h3" },
    pen: { d: "M11.35 2.65a1.35 1.35 0 0 1 1.9 1.9L8.6 9.2l-2.35.55.55-2.35Z" },
  },
  settings: {
    rails: { d: "M2.75 4.5h4.5M10.25 4.5h3M2.75 11.5h1.5M7.25 11.5h6" },
    knobs: { d: "M8.75 3v3M5.75 10v3" },
  },
  help: {
    ring: { d: RING },
    hook: { d: "M6.25 6.4a1.8 1.8 0 1 1 2.55 1.65c-.5.25-.8.6-.8 1.1v.25" },
    dot: { d: "M8 11.25 L8 11.26" },
  },
  clock: {
    ring: { d: RING },
    hands: { d: "M8 4.75v3.5l2.25 1.5" },
  },
  share: {
    arrow: { d: "M8 9.75v-7M5.25 5.25 8 2.5l2.75 2.75", fx: "lid" },
    tray: { d: "M4.75 7.5h-.5a1.5 1.5 0 0 0-1.5 1.5v2.75a1.5 1.5 0 0 0 1.5 1.5h7.5a1.5 1.5 0 0 0 1.5-1.5V9a1.5 1.5 0 0 0-1.5-1.5h-.5" },
  },
  folder: {
    body: { d: "M2.75 4.75a1.5 1.5 0 0 1 1.5-1.5h2.3l1.4 1.5h3.8a1.5 1.5 0 0 1 1.5 1.5v5.5a1.5 1.5 0 0 1-1.5 1.5h-7.5a1.5 1.5 0 0 1-1.5-1.5Z" },
  },
  paperclip: {
    clip: { d: "M12.75 7.25 8.1 11.9a2.9 2.9 0 0 1-4.1-4.1l4.85-4.85a1.85 1.85 0 0 1 2.6 2.6L6.6 10.4a.8.8 0 0 1-1.1-1.1l4.35-4.35" },
  },
  at: {
    ring: { d: "M10.5 8v.9a1.85 1.85 0 0 0 3.7 0V8a6.2 6.2 0 1 0-2.45 4.95" },
    core: { d: "M10.5 8a2.5 2.5 0 1 1-5 0a2.5 2.5 0 1 1 5 0" },
  },
  list: {
    lines: { d: "M6.75 4.5h6.5M6.75 8h6.5M6.75 11.5h6.5" },
    dots: { d: "M3.25 4.5h.01M3.25 8h.01M3.25 11.5h.01" },
  },
  terminal: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    prompt: { d: "M5.25 6.25 7 8l-1.75 1.75M8.5 10h2.25" },
  },
  branch: {
    a: { d: "M6.25 4a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    b: { d: "M6.25 12a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    c: { d: "M12.25 5a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    trunk: { d: "M5 5.25v5.5" },
    twig: { d: "M11 6.25v.5a3 3 0 0 1-3 3H7.25a2.25 2.25 0 0 0-2.25 1" },
  },
  /* An amount of effort: a dial and its needle. */
  gauge: {
    dial: { d: "M2.75 11.75a5.25 5.25 0 1 1 10.5 0" },
    needle: { d: "M8 11.75l2.5-3.5" },
  },
  /* A panel with its column on the other side: show or hide a side panel at the end. */
  panel: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M9.75 2.75 L9.75 13.25" },
  },
  /* What happened to a file: one rounded square, and inside it a plus, a
     dot, a minus or an arrow. They share the square and the bar, so a file
     whose change kind moves morphs only the mark. */
  "diff-added": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    stem: { d: "M8 10.5 L8 5.5" },
  },
  "diff-modified": {
    frame: { d: CHANGE_FRAME },
    dot: { d: "M8 8 L8.01 8", block: true },
  },
  "diff-removed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
  },
  "diff-renamed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    head: { d: "M8.5 6 L10.5 8 L8.5 10" },
  },
} satisfies Record<string, Record<string, Stroke>>;

export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* Shared field parts to compose. */

  .field {
    display: grid;
    /* The field's width, not its input's: an input's default size (about 20
       characters) would otherwise push a narrow form sideways. */
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ui-space-2);
    min-width: 0;
    font-family: var(--ui-font-sans);
  }

  .label {
    justify-self: start;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .shell {
    --edge: var(--ui-border-strong);
    --edge-width: var(--ui-hairline);
    --shell-inset: calc((var(--ui-control-md) - var(--ui-control-sm)) / 2);
    position: relative;
    height: var(--ui-control-md);
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--edge-width) var(--edge);
    transition: box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .shell:hover:not(:focus-within, [data-invalid], [data-disabled], [data-open]) {
      --edge: var(--ui-field-focus);
    }
  }

  .shell:focus-within,
  .shell[data-open] {
    --edge: var(--ui-field-focus);
    --edge-width: 1px;
    box-shadow: inset 0 0 0 var(--edge-width) var(--edge);
    transition-duration: 0s;
  }

  .shell[data-open] {
    transition-duration: var(--ui-dur-instant);
  }

  .shell[data-invalid] {
    --edge: var(--ui-danger);
  }

  .shell[data-disabled] {
    opacity: 0.5;
  }

  .bare {
    min-width: 0;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    outline: none;
  }

  .bare::placeholder {
    color: var(--ui-subtle);
  }

  .bare:disabled {
    cursor: default;
  }

  /* iOS zooms the page into any field under 16px. */
  @media (pointer: coarse) {
    .bare {
      font-size: var(--ui-text-touch);
    }
  }

  /* Inset button. Set its radius where it sits (outer radius less the inset). */
  .inset {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    position: relative;
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: var(--ui-control-sm);
    height: var(--ui-control-sm);
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-md) - var(--shell-inset, 4px));
    background: none;
    color: var(--ui-muted);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .inset::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .inset > * {
    position: relative;
  }

  @media (hover: hover) {
    .inset:hover:not(:disabled, [aria-disabled]) {
      color: var(--ui-foreground);
    }
    .inset:hover:not(:disabled, [aria-disabled])::before {
      background: var(--ui-fill);
    }
  }

  .inset:active:not(:disabled, [aria-disabled]) {
    color: var(--ui-foreground);
  }

  .inset:active:not(:disabled, [aria-disabled])::before {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .inset:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
    color: var(--ui-foreground);
  }

  .inset:disabled,
  .inset[aria-disabled] {
    cursor: default;
  }

  /* 32px to look at, 40px to hit. */
  @media (pointer: coarse) {
    .inset::after {
      content: "";
      position: absolute;
      inset: -4px;
    }
  }

  .message {
    display: grid;
    min-height: var(--ui-leading-md);
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .hint,
  .error {
    grid-area: 1 / 1;
    min-width: 0;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .hint[data-shown],
  .error[data-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @starting-style {
    .error[data-shown] {
      opacity: 0;
    }
  }

  .hint {
    color: var(--ui-muted);
  }

  .error {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    color: var(--ui-danger-text);
  }

  .errorIcon {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    margin-top: calc((var(--ui-leading-md) - 14px) / 2);
    --ui-icon-stroke: calc(var(--ui-icon-stroke-regular) * 16 / 14);
  }

  .error[data-shown] .errorText {
    animation: field-error-swap var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes field-error-swap {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .inset:active:not(:disabled, [aria-disabled])::before {
      scale: none;
    }
    .error[data-shown] .errorText {
      animation: none;
    }
  }
}

"use client";

import { useState } from "react";
import { Icon } from "../icons/icons";
import styles from "./field.module.css";

type FieldMessageProps = {
  id: string;
  hint?: string | null;
  error?: string | null;
};

/** Hint or error; the hidden one leaves the description and live region. */
export function FieldMessage({ id, hint, error }: FieldMessageProps) {
  const [lastError, setLastError] = useState(error);
  if (error && error !== lastError) setLastError(error);

  return (
    <p id={id} className={styles.message} aria-live="polite">
      {hint && (
        <span className={styles.hint} data-shown={!error || undefined}>
          {hint}
        </span>
      )}
      {lastError && (
        <span className={styles.error} data-shown={error ? true : undefined}>
          <Icon name="alert" className={styles.errorIcon} />
          <span key={lastError} className={styles.errorText}>
            {lastError}
          </span>
        </span>
      )}
    </p>
  );
}

@layer theme, base, components, utilities;

/* Registered so the edge alphas can transition. */
@property --scroll-area-start {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@property --scroll-area-end {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@layer components {
  /* The focus ring lives here because the viewport's mask would fade it out. */
  .root {
    position: relative;
    display: flex;
    flex-direction: column;
    min-width: 0;
    min-height: 0;
  }

  .root:has(> .viewport:focus-visible) {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .viewport {
    --scroll-area-fade: var(--ui-space-6, 32px);
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
    border-radius: inherit;
    outline: none;
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
  }

  .viewport[data-orientation="vertical"] {
    overflow-x: hidden;
    overflow-y: auto;
    scroll-padding-block: var(--scroll-area-fade);
  }

  /* Stops a sideways swipe at the end from triggering browser back. */
  .viewport[data-orientation="horizontal"] {
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-inline: contain;
    scroll-padding-inline: var(--scroll-area-fade);
  }

  /* One fade layer over the whole viewport, scrollbar included: a solid
     strip kept for a classic scrollbar also left a sliver of each row at full
     opacity beside it. */
  .viewport[data-fade] {
    mask-image: linear-gradient(
      var(--scroll-area-direction, to bottom),
      rgb(0 0 0 / var(--scroll-area-start, 1)),
      black var(--scroll-area-fade, 32px),
      black calc(100% - var(--scroll-area-fade, 32px)),
      rgb(0 0 0 / var(--scroll-area-end, 1))
    );
  }

  .viewport[data-fade][data-orientation="horizontal"] {
    --scroll-area-direction: to right;
  }

  :is([dir="rtl"]) .viewport[data-fade][data-orientation="horizontal"] {
    --scroll-area-direction: to left;
  }

  @supports (animation-timeline: scroll()) {
    .viewport[data-fade] {
      animation:
        scroll-area-start linear both,
        scroll-area-end linear both;
      animation-timeline: scroll(self block), scroll(self block);
      animation-range:
        0 var(--scroll-area-fade),
        calc(100% - var(--scroll-area-fade)) 100%;
    }

    .viewport[data-fade][data-orientation="horizontal"] {
      animation-timeline: scroll(self inline), scroll(self inline);
    }

    /* Chromium keeps an animation's last value once its timeline goes inactive;
       the script sets data-fits so stale fades clear. */
    .viewport[data-fade][data-fits] {
      animation: none;
    }
  }

  @keyframes scroll-area-start {
    from {
      --scroll-area-start: 1;
    }
    to {
      --scroll-area-start: 0;
    }
  }

  @keyframes scroll-area-end {
    from {
      --scroll-area-end: 0;
    }
    to {
      --scroll-area-end: 1;
    }
  }

  /* Script fallback; data-ready skips the transition on first paint. */
  @supports not (animation-timeline: scroll()) {
    .viewport[data-fade][data-ready] {
      transition:
        --scroll-area-start var(--ui-dur-fast) var(--ui-ease-color),
        --scroll-area-end var(--ui-dur-fast) var(--ui-ease-color);
    }
  }

  .content {
    display: flow-root;
  }

  .viewport[data-orientation="horizontal"] > .content {
    width: max-content;
    min-width: 100%;
  }
}

"use client";

import { useLayoutEffect, useRef, useState, type ComponentProps, type Ref } from "react";
import styles from "./scroll-area.module.css";

type ScrollAreaProps = Omit<ComponentProps<"div">, "ref"> & {
  /** Accessible name; makes the area a named region. */
  label?: string;
  orientation?: "vertical" | "horizontal";
  /** Fade edges that have more content past them. */
  fade?: boolean;
  /** The scrolling element. */
  ref?: Ref<HTMLDivElement>;
};

const FOCUSABLE =
  'a[href], area[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), iframe, summary, [contenteditable]:not([contenteditable="false"]), [tabindex]:not([tabindex="-1"])';

/** A scroll container whose edges fade where there's more content past them. */
export function ScrollArea({
  label,
  orientation = "vertical",
  fade = true,
  className,
  style,
  children,
  ref,
  "aria-labelledby": labelledBy,
  ...props
}: ScrollAreaProps) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  // Keyboard users need a tab stop to scroll, but only when nothing inside is focusable.
  const [tabStop, setTabStop] = useState(false);

  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    const content = contentRef.current;
    if (!viewport || !content) return;
    const vertical = orientation === "vertical";
    const cssFades = typeof CSS !== "undefined" && CSS.supports("animation-timeline: scroll()");
    let frame = 0;
    let ready = false;

    const measure = () => {
      const pos = Math.abs(vertical ? viewport.scrollTop : viewport.scrollLeft);
      const max = vertical
        ? viewport.scrollHeight - viewport.clientHeight
        : viewport.scrollWidth - viewport.clientWidth;
      viewport.toggleAttribute("data-fits", max <= 1);
      if (!cssFades) {
        viewport.style.setProperty("--scroll-area-start", pos > 1 ? "0" : "1");
        viewport.style.setProperty("--scroll-area-end", pos < max - 1 ? "0" : "1");
      }
      const bar = vertical ? viewport.offsetWidth - viewport.clientWidth : viewport.offsetHeight - viewport.clientHeight;
      viewport.style.setProperty("--scroll-area-bar", `${Math.max(0, bar)}px`);
      setTabStop(max > 1 && content.querySelector(FOCUSABLE) === null);
      if (!ready) {
        ready = true;
        frame = requestAnimationFrame(() => {
          viewport.dataset.ready = "";
        });
      }
    };

    let pending = 0;
    const onScroll = () => {
      if (pending) return;
      pending = requestAnimationFrame(() => {
        pending = 0;
        measure();
      });
    };

    // Vertical wheel scrolls a horizontal row until it hits an end, then the page.
    const onWheel = (event: WheelEvent) => {
      if (vertical || event.ctrlKey || event.shiftKey) return;
      if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
      const max = viewport.scrollWidth - viewport.clientWidth;
      if (max <= 1) return;
      const rtl = getComputedStyle(viewport).direction === "rtl";
      const step = event.deltaMode === 1 ? event.deltaY * 16 : event.deltaMode === 2 ? event.deltaY * viewport.clientWidth : event.deltaY;
      const pos = Math.abs(viewport.scrollLeft);
      const forward = step > 0;
      if ((forward && pos >= max - 1) || (!forward && pos <= 1)) return;
      event.preventDefault();
      viewport.scrollLeft += rtl ? -step : step;
    };

    measure();
    viewport.addEventListener("scroll", onScroll, { passive: true });
    viewport.addEventListener("wheel", onWheel, { passive: false });
    const resize = new ResizeObserver(measure);
    resize.observe(viewport);
    resize.observe(content);
    const mutation = new MutationObserver(measure);
    mutation.observe(content, { childList: true, subtree: true, attributes: true, attributeFilter: ["disabled", "tabindex", "href"] });

    return () => {
      cancelAnimationFrame(frame);
      cancelAnimationFrame(pending);
      viewport.removeEventListener("scroll", onScroll);
      viewport.removeEventListener("wheel", onWheel);
      resize.disconnect();
      mutation.disconnect();
      delete viewport.dataset.ready;
      viewport.removeAttribute("data-fits");
    };
  }, [orientation]);

  function setRefs(node: HTMLDivElement | null) {
    viewportRef.current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) ref.current = node;
  }

  const named = Boolean(label || labelledBy);

  return (
    <div className={className ? `${styles.root} ${className}` : styles.root} style={style} data-orientation={orientation}>
      <div
        ref={setRefs}
        className={styles.viewport}
        data-orientation={orientation}
        data-fade={fade ? "" : undefined}
        role={named ? "region" : undefined}
        aria-label={label}
        aria-labelledby={labelledBy}
        tabIndex={tabStop ? 0 : undefined}
        {...props}
      >
        <div ref={contentRef} className={styles.content}>
          {children}
        </div>
      </div>
    </div>
  );
}

@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

.root {
  composes: field from "../field/field.module.css";
}

.label {
  composes: label from "../field/field.module.css";
}

.constraints {
  composes: wrap from "../text/text.module.css";
}

.name {
  composes: wrap from "../text/text.module.css";
}

.icon {
  composes: inset from "../field/field.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .root {
    --upload-height: 248px;
    interpolate-size: allow-keywords;
  }

  .zone {
    --zone-pad: var(--ui-space-1);
    --row-height: calc(var(--ui-control-md) + var(--ui-space-4));
    --badge-size: var(--ui-control-md);
    --row-inset: calc((var(--row-height) - var(--badge-size)) / 2);
    --item-radius: calc(var(--inner-radius) - var(--row-inset));
    --inner-radius: calc(var(--ui-radius-lg) - var(--zone-pad));
    --zone-bg: var(--ui-canvas);
    --zone-edge: var(--ui-border-strong);
    position: relative;
    display: grid;
    /* minmax(0, …) so long names truncate instead of widening the well. */
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: 1fr;
    height: var(--upload-height);
    padding: var(--zone-pad);
    border-radius: var(--ui-radius-lg);
    background: var(--zone-bg);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--zone-edge);
    font-family: var(--ui-font-sans);
    transition:
      box-shadow var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .zone[data-has] {
    grid-template-rows: minmax(0, 1fr) auto;
    --zone-bg: var(--ui-surface);
  }

  /* The empty well answers the pointer like a field: its edge darkens, and
     nothing fills or shrinks. A press needs no state of its own; the picker
     opening is the answer. */
  @media (hover: hover) {
    .zone:not([data-has], [data-disabled], [data-dragging]):has(.browse:hover) {
      --zone-edge: var(--ui-field-focus);
    }
  }

  /* The one state that has to read from across the screen: a file held over
     the zone. The edge takes the focused field's color, the well tints a step,
     and the prompt comes up to the text color. */
  .zone[data-dragging] {
    --zone-bg: color-mix(in oklch, var(--ui-canvas), var(--ui-foreground) 5%);
    --zone-edge: var(--ui-field-focus);
  }

  .zone[data-has][data-dragging] {
    --zone-bg: var(--ui-fill-solid);
  }

  .zone[data-disabled] {
    opacity: 0.5;
  }

  .input {
    display: none;
  }

  /* ---------- Browse ---------- */

  .browse {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--ui-space-2);
    min-height: 0;
    padding: var(--ui-space-4);
    border: 0;
    border-radius: var(--inner-radius);
    background: none;
    color: var(--ui-foreground);
    font: inherit;
    text-align: center;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .zone[data-has] .browse {
    flex-direction: row;
    justify-content: flex-start;
    gap: var(--ui-space-3);
    min-height: var(--row-height);
    padding: 0 var(--row-inset);
    text-align: start;
    color: var(--ui-muted);
  }

  .zone[data-has] .browse::after {
    content: "";
    position: absolute;
    inset: 0 var(--row-inset) auto;
    height: var(--ui-hairline);
    background: var(--ui-border);
  }

  /* The "Add more files" bar is a row in a list, so it takes a row's hover:
     the text comes up to the text color. No fill, and no press state. */
  @media (hover: hover) {
    .zone[data-has] .browse:hover:not(:disabled) {
      color: var(--ui-foreground);
    }
  }

  .zone[data-dragging] .browse,
  .zone[data-dragging] .mark {
    color: var(--ui-foreground);
  }

  .browse:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .browse:disabled {
    cursor: default;
  }

  .mark {
    display: grid;
    place-items: center;
    color: var(--ui-muted);
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .zone[data-has] .mark {
    flex-shrink: 0;
    width: var(--badge-size);
    color: inherit;
  }

  .prompt {
    display: grid;
    gap: 2px;
    min-width: 0;
  }

  .zone[data-has] .prompt {
    display: flex;
    flex: 1;
    align-items: baseline;
  }

  .zone[data-has] .action {
    flex-shrink: 0;
    white-space: nowrap;
  }

  /* Visually hidden, not removed: the button uses them as its description. */
  .zone[data-has] .constraints {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .action {
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .constraints {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .constraints:empty {
    display: none;
  }

  /* ---------- Files ---------- */

  .scroll {
    min-height: 0;
    border-radius: var(--inner-radius);
  }

  .list {
    display: grid;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .row {
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ui-space-3);
    height: var(--row-height);
    padding-inline: var(--row-inset);
    overflow: hidden;
    border-radius: var(--inner-radius);
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    animation: upload-row-in var(--ui-dur-base) var(--ui-ease-enter);
  }

  .row + .row::after {
    content: "";
    position: absolute;
    inset: 0 var(--row-inset) auto calc(var(--row-inset) + var(--badge-size) + var(--ui-space-3));
    height: var(--ui-hairline);
    background: var(--ui-border);
  }

  .row > * {
    position: relative;
  }

  /* Clipped, not scaled, so its corners keep the row's radius. */
  .wash {
    position: absolute !important;
    inset: 0;
    border-radius: inherit;
    background: var(--ui-fill);
    clip-path: inset(0 calc((1 - var(--progress)) * 100%) 0 0);
    transition:
      clip-path var(--ui-dur-move) var(--ui-ease-move),
      opacity var(--ui-dur-base) var(--ui-ease-color);
  }

  :is([dir="rtl"]) .wash {
    clip-path: inset(0 0 0 calc((1 - var(--progress)) * 100%));
  }

  .row[data-status="done"] .wash {
    opacity: 0;
    transition-delay: 0s, var(--ui-dur-move);
  }

  .row:is([data-status="failed"], [data-status="rejected"]) .wash {
    background: var(--ui-danger-tint);
  }

  .row[data-status="rejected"] .wash {
    clip-path: none;
  }

  .row[data-leaving] {
    animation:
      upload-row-fade var(--ui-dur-instant) var(--ui-ease-exit) forwards,
      upload-row-close var(--ui-dur-base) var(--ui-ease-collapse) var(--ui-dur-instant) forwards;
  }

  @keyframes upload-row-in {
    from {
      opacity: 0;
      translate: 0 4px;
    }
  }

  @keyframes upload-row-fade {
    to {
      opacity: 0;
    }
  }

  @keyframes upload-row-close {
    to {
      height: 0;
    }
  }

  .badge {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: var(--badge-size);
    height: var(--badge-size);
    border-radius: var(--item-radius);
    background: var(--ui-fill);
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: 1;
  }

  .row[data-status="done"] .badge {
    color: var(--ui-foreground);
  }

  .row:is([data-status="failed"], [data-status="rejected"]) .badge {
    background: var(--ui-danger-tint);
    color: var(--ui-danger-text);
  }

  .text {
    display: grid;
    flex: 1;
    min-width: 0;
  }

  .name {
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
  }

  .meta {
    overflow: hidden;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    overflow-wrap: anywhere;
  }

  .row[data-status="uploading"] .meta {
    font-variant-numeric: tabular-nums;
  }

  .row:is([data-status="failed"], [data-status="rejected"]) .meta {
    color: var(--ui-danger-text);
  }

  /* Room for retry is kept on every row, so a failure moves nothing. */
  .actions {
    display: flex;
    flex-shrink: 0;
    justify-content: flex-end;
    gap: 2px;
    width: calc(var(--badge-size) * 2 + 2px);
  }

  /* Doubled so it outranks the inset rule in any stylesheet order. */
  .icon.icon {
    width: var(--badge-size);
    height: var(--badge-size);
    border-radius: var(--item-radius);
  }

  @media (prefers-reduced-motion: reduce) {
    .row,
    .row[data-leaving] {
      animation: none;
    }
    .wash {
      transition: none;
    }
  }
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type CSSProperties, type DragEvent } from "react";
import { Icon } from "../icons/icons";
import { ScrollArea } from "../scroll-area/scroll-area";
import styles from "./file-upload.module.css";

export type UploadStatus = "uploading" | "done" | "failed" | "rejected";

export type UploadItem = {
  id: string;
  file: File;
  status: UploadStatus;
  /** 0 to 1 while uploading. */
  progress: number;
  /** Why it failed or was rejected, in plain words. */
  error?: string;
};

type Upload = (file: File, options: { signal: AbortSignal; onProgress: (fraction: number) => void }) => Promise<void>;

type FileUploadProps = {
  label: string;
  /** Sends one file; report progress, throw to fail it. */
  upload: Upload;
  /** As on a file input: ".pdf,image/*". */
  accept?: string;
  /** Plain words for `accept`, like "PDF, JPG or PNG". */
  acceptLabel?: string;
  /** Largest file, in bytes. */
  maxSize?: number;
  maxFiles?: number;
  onChange?: (items: UploadItem[]) => void;
  disabled?: boolean;
  className?: string;
};

function formatBytes(bytes: number) {
  const units = ["bytes", "KB", "MB", "GB"];
  let n = bytes;
  let u = 0;
  while (n >= 1000 && u < units.length - 1) {
    n /= 1000;
    u++;
  }
  return `${u === 0 ? n : n.toFixed(n < 10 ? 1 : 0)} ${units[u]}`;
}

function accepts(file: File, accept?: string) {
  if (!accept) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return accept
    .split(",")
    .map((a) => a.trim().toLowerCase())
    .some((a) => (a.startsWith(".") ? name.endsWith(a) : a.endsWith("/*") ? type.startsWith(a.slice(0, -1)) : type === a));
}

/** "receipt.final.jpeg" → "JPEG"; no extension → "FILE". */
function extension(name: string) {
  const dot = name.lastIndexOf(".");
  const ext = dot > 0 ? name.slice(dot + 1) : "";
  return (ext.length > 0 && ext.length <= 4 ? ext : "file").toUpperCase();
}

let counter = 0;

/** A drop zone with a list of uploads in a fixed-height panel. */
export function FileUpload({
  label,
  upload,
  accept,
  acceptLabel,
  maxSize,
  maxFiles,
  onChange,
  disabled = false,
  className,
}: FileUploadProps) {
  const baseId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const browseRef = useRef<HTMLButtonElement>(null);
  const refocus = useRef(false);
  const controllers = useRef(new Map<string, AbortController>());
  const depth = useRef(0);
  const [items, setItems] = useState<UploadItem[]>([]);
  const [leaving, setLeaving] = useState<Set<string>>(() => new Set());
  const [dragging, setDragging] = useState(false);
  const [announcement, setAnnouncement] = useState("");

  // Report changes after they're committed, never while rendering.
  const reported = useRef(items);
  useEffect(() => {
    if (reported.current !== items) {
      reported.current = items;
      onChange?.(items);
    }
  }, [items, onChange]);

  useEffect(() => {
    const map = controllers.current;
    return () => map.forEach((c) => c.abort());
  }, []);

  const patch = (id: string, next: Partial<UploadItem>) =>
    setItems((list) => list.map((item) => (item.id === id ? { ...item, ...next } : item)));

  function start(id: string, file: File) {
    const controller = new AbortController();
    controllers.current.get(id)?.abort();
    controllers.current.set(id, controller);
    patch(id, { status: "uploading", progress: 0, error: undefined });
    upload(file, {
      signal: controller.signal,
      onProgress: (fraction) => {
        if (!controller.signal.aborted) patch(id, { progress: Math.min(Math.max(fraction, 0), 1) });
      },
    }).then(
      () => {
        if (controller.signal.aborted) return;
        controllers.current.delete(id);
        patch(id, { status: "done", progress: 1 });
        setAnnouncement(`${file.name} uploaded`);
      },
      (reason: unknown) => {
        if (controller.signal.aborted) return;
        controllers.current.delete(id);
        const message = reason instanceof Error && reason.message ? reason.message : "Upload failed. Try again.";
        patch(id, { status: "failed", error: message });
        setAnnouncement(`${file.name} didn’t upload: ${message}`);
      },
    );
  }

  function add(files: FileList | File[]) {
    if (disabled) return;
    const kept = items.filter((i) => i.status !== "rejected").length;
    const next: UploadItem[] = [];
    let room = maxFiles === undefined ? Infinity : maxFiles - kept;
    for (const file of files) {
      const id = `${baseId}-${++counter}`;
      let error: string | undefined;
      if (!accepts(file, accept)) error = acceptLabel ? `Not a ${acceptLabel} file` : "This kind of file can’t be added";
      else if (maxSize !== undefined && file.size > maxSize) error = `Too large: ${formatBytes(file.size)}. Up to ${formatBytes(maxSize)}.`;
      else if (room <= 0) error = `Only ${maxFiles} files can be added`;
      else room--;
      next.push({ id, file, status: error ? "rejected" : "uploading", progress: 0, error });
    }
    if (next.length === 0) return;
    refocus.current = document.activeElement === browseRef.current;
    setItems((list) => [...list, ...next]);
    const rejected = next.filter((n) => n.error);
    if (rejected.length) setAnnouncement(rejected.map((r) => `${r.file.name}: ${r.error}`).join(". "));
    for (const item of next) if (!item.error) start(item.id, item.file);
  }

  function remove(id: string) {
    controllers.current.get(id)?.abort();
    controllers.current.delete(id);
    const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) setItems((list) => list.filter((i) => i.id !== id));
    else setLeaving((s) => new Set(s).add(id));
  }

  function forget(id: string) {
    setItems((list) => list.filter((i) => i.id !== id));
    setLeaving((s) => {
      const next = new Set(s);
      next.delete(id);
      return next;
    });
  }

  // Enter and leave fire on each child; count them so the highlight doesn't flicker.
  const onDragEnter = (event: DragEvent) => {
    if (disabled || !event.dataTransfer.types.includes("Files")) return;
    event.preventDefault();
    depth.current++;
    setDragging(true);
  };
  const onDragLeave = () => {
    depth.current = Math.max(0, depth.current - 1);
    if (depth.current === 0) setDragging(false);
  };
  const onDrop = (event: DragEvent) => {
    event.preventDefault();
    depth.current = 0;
    setDragging(false);
    if (event.dataTransfer.files.length) add(event.dataTransfer.files);
  };

  const has = items.length > 0;
  // The prompt and the bar are different elements, so focus must follow the swap.
  useLayoutEffect(() => {
    if (refocus.current) browseRef.current?.focus();
    refocus.current = false;
  }, [has]);

  const constraints = [acceptLabel, maxSize !== undefined && `up to ${formatBytes(maxSize)}`].filter(Boolean).join(", ");

  const browseButton = (
    <button
      key={has ? "bar" : "empty"}
      ref={browseRef}
      type="button"
      className={styles.browse}
      disabled={disabled}
      aria-describedby={`${baseId}-constraints`}
      aria-labelledby={`${baseId}-label ${baseId}-action`}
      onClick={() => inputRef.current?.click()}
    >
      <span className={styles.mark}>
        <Icon name={has ? "plus" : "upload"} />
      </span>
      <span className={styles.prompt}>
        <span id={`${baseId}-action`} className={styles.action}>
          {dragging ? "Drop to add" : has ? "Add more files" : "Drop files here or browse"}
        </span>
        <span id={`${baseId}-constraints`} className={styles.constraints}>
          {constraints}
        </span>
      </span>
    </button>
  );

  return (
    <div className={className ? `${styles.root} ${className}` : styles.root}>
      <span id={`${baseId}-label`} className={styles.label}>
        {label}
      </span>
      <div
        className={styles.zone}
        data-dragging={dragging || undefined}
        data-has={has || undefined}
        data-disabled={disabled || undefined}
        onDragEnter={onDragEnter}
        onDragOver={(e) => {
          if (!disabled && e.dataTransfer.types.includes("Files")) e.preventDefault();
        }}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
      >
        <input
          ref={inputRef}
          type="file"
          className={styles.input}
          accept={accept}
          multiple={maxFiles !== 1}
          disabled={disabled}
          tabIndex={-1}
          aria-hidden="true"
          onChange={(e) => {
            if (e.currentTarget.files) add(e.currentTarget.files);
            // The same file can be picked again after it's removed.
            e.currentTarget.value = "";
          }}
        />
        {!has && browseButton}
        {has && (
          <ScrollArea className={styles.scroll}>
            <ul className={styles.list} aria-labelledby={`${baseId}-label`}>
              {items.map((item) => (
                <Row
                  key={item.id}
                  item={item}
                  leaving={leaving.has(item.id)}
                  onRetry={() => start(item.id, item.file)}
                  onRemove={() => remove(item.id)}
                  onGone={() => forget(item.id)}
                />
              ))}
            </ul>
          </ScrollArea>
        )}
        {has && browseButton}
      </div>
      <span className={styles.srOnly} aria-live="polite">
        {announcement}
      </span>
    </div>
  );
}

function Row({
  item,
  leaving,
  onRetry,
  onRemove,
  onGone,
}: {
  item: UploadItem;
  leaving: boolean;
  onRetry: () => void;
  onRemove: () => void;
  onGone: () => void;
}) {
  const { file, status, progress, error } = item;
  const meta =
    status === "uploading"
      ? `${Math.round(progress * 100)}% of ${formatBytes(file.size)}`
      : status === "done"
        ? `Uploaded, ${formatBytes(file.size)}`
        : error;

  return (
    <li
      className={styles.row}
      data-status={status}
      data-leaving={leaving || undefined}
      inert={leaving || undefined}
      onAnimationEnd={(e) => {
        // The fade ends first; the row goes once its space has closed.
        if (leaving && e.target === e.currentTarget && e.animationName.includes("close")) onGone();
      }}
    >
      <span className={styles.wash} aria-hidden="true" style={{ "--progress": progress } as CSSProperties} />
      <span className={styles.badge} aria-hidden="true">
        {status === "done" ? <Icon name="check" /> : extension(file.name)}
      </span>
      <span className={styles.text}>
        <span className={styles.name} title={file.name}>
          {file.name}
        </span>
        <span className={styles.meta}>{meta}</span>
      </span>
      <span className={styles.actions}>
        {status === "failed" && (
          <button type="button" className={styles.icon} aria-label={`Retry ${file.name}`} onClick={onRetry}>
            <Icon name="retry" />
          </button>
        )}
        <button
          type="button"
          className={styles.icon}
          aria-label={status === "uploading" ? `Cancel ${file.name}` : `Remove ${file.name}`}
          onClick={onRemove}
        >
          <Icon name="close" />
        </button>
      </span>
    </li>
  );
}
